(function(outputs, steps, params, stepResult, assertEqual) {
    var step6 = 'a72db2ae831ec7101902ba96feaad35c';

    // 1. Get the Sys ID of the RITM found in Step 6
    var ritmSysId = steps(step6).first_record;

    // 2. Query the actual RITM table to find its human-readable number string
    var ritmGr = new GlideRecord('sc_req_item');
    var generatedRitmNumber = '';
    if (ritmGr.get(ritmSysId)) {
        generatedRitmNumber = ritmGr.getValue('number');
    }

    // 3. Build the dynamic subject line using your exact test parameter syntax
   // var expectedSubject = 'Workspace Reservation Request Rejected for ' + 'Hot Desk A-101'; //+ params.u_hot_desk;
	var expectedSubject = params.u_email_subject + ' ' + params.u_workspace; //+ params.u_hot_desk;


    // 4. Directly query the sys_email table to locate the outbound message
    var emailGr = new GlideRecord('sys_email');
    emailGr.addEncodedQuery('sys_created_on>=javascript:gs.minutesAgo(5)');
    emailGr.addQuery('subject', 'CONTAINS', expectedSubject);
    emailGr.query();

    if (emailGr.next()) {
        // EXTRACT EMAIL ID: Captures the unique system ID of the generated notification
        var emailSysId = emailGr.getUniqueValue();

        // 5. OUTPUT MESSAGE: Displays RITM, RITM Sys ID, Email Sys ID, and Subject Line on a single row
        var visualConfirmation = 'REJECTION & EMAIL VERIFIED >> RITM: [' + generatedRitmNumber + '] | RITM Sys ID: [' + ritmSysId + '] | Email Sys ID: [' + emailSysId + '] | Outbound Subject Line Confirmed: [' + expectedSubject + ']';

        stepResult.setOutputMessage(visualConfirmation);
        stepResult.setSuccess();
    } else {
        stepResult.setOutputMessage('Failure: Could not locate an outbound test email in the queue matching subject line: ' + expectedSubject);
        stepResult.setFailed();
    }

})(outputs, steps, params, stepResult, assertEqual);
// uncomment the next line to execute this script as a jasmine test
